using BrudvikWhiteHilt.Helpers;
using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.Dewberries;

/// <summary>
/// Dewberries, blue-black berries with a misty bloom on a low bramble in the Mistlands. Model: generated by
/// AssetSource/Tools/make_forage_models.py; the berries hide when picked. Jotun Puffs picked in the Mistlands can also
/// give them.
/// </summary>
public class Dewberries : ForageableBase
{
    /// <summary>
    /// Prefab name of the dewberries item.
    /// </summary>
    public const string PrefabName = "WhiteHiltDewberries";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Dewberries";

    /// <inheritdoc/>
    protected override string Description => "Blue-black berries with a misty bloom, from a low bramble that trails over the stones in the mist. Sweet, and wet with dew.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Blueberries";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "BlueberryBush";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.Mistlands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 2,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 3,
        GroupRadius = 4f,
        MinAltitude = 1f,
        MaxTilt = 30f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => "Pickable_Mushroom_JotunPuffs";

    /// <inheritdoc/>
    protected override float ExtraDropChance => 0.25f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        // Blueberries take a misty, bluer cast.
        VisualHelper.Tint(visualRoot, new Color(0.8f, 0.85f, 1f));
    }

    /// <inheritdoc/>
    protected override void ApplyPickableVisual(GameObject pickablePrefab, Pickable pickable)
    {
        ReplaceBushMesh(pickablePrefab, pickable, "dewberry", 0.55f);
    }
}
